    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]
    rmin, rmax = min(r for r, _ in cells), max(r for r, _ in cells)
    cmin, cmax = min(c for _, c in cells), max(c for _, c in cells)
    size = 1
    for s in range(1, min(rmax-rmin+1, cmax-cmin+1)+1):
        if all((r-rmin) % s == 0 and (c-cmin) % s == 0 for r, c in cells):
            # Candidate must tile the object's bounding box and give a macro mask.
            if (rmax-rmin+1) % s == 0 and (cmax-cmin+1) % s == 0:
                size = s
    # Determine macro cells by requiring each macro block to be entirely 8 or empty.
    mask = {}
    for r in range(rmin, rmax+1, size):
        for c in range(cmin, cmax+1, size):
            vals = {grid[rr][cc] for rr in range(r, min(r+size, h)) for cc in range(c, min(c+size, w))}
            if vals == {8}:
                mask[((r-rmin)//size, (c-cmin)//size)] = True
    # Colored key coordinates (all nonzero, non-8 cells) rotate clockwise.
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not key:
        return [row[:] for row in grid]
    kr0, kr1 = min(r for r, _, _ in key), max(r for r, _, _ in key)
    kc0 = min(c for _, c, _ in key)
    rotated = {}
    for r, c, color in key:
        # 90-degree clockwise rotation within the key's bounding rectangle.
        rr, cc = c-kc0, kr1-r
        rotated[(rr, cc)] = color
    out = [row[:] for row in grid]
    for (mr, mc), _ in mask.items():
        color = rotated.get((mr, mc))
        if color is not None:
            for rr in range(rmin+mr*size, rmin+(mr+1)*size):
                for cc in range(cmin+mc*size, cmin+(mc+1)*size):
                    out[rr][cc] = color
    return out

