from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not eight:
        return [row[:] for row in grid]
    r0, r1 = min(r for r,c in eight), max(r for r,c in eight)
    c0, c1 = min(c for r,c in eight), max(c for r,c in eight)
    runs = []
    for r in range(r0, r1+1):
        run = 0
        for c in range(c0, c1+2):
            if c <= c1 and grid[r][c] == 8:
                run += 1
            elif run:
                runs.append(run)
                run = 0
    for c in range(c0, c1+1):
        run = 0
        for r in range(r0, r1+2):
            if r <= r1 and grid[r][c] == 8:
                run += 1
            elif run:
                runs.append(run)
                run = 0
    unit = reduce(gcd, runs)
    nr, nc = (r1-r0+1)//unit, (c1-c0+1)//unit
    mask = [[all(grid[r0+i*unit+dr][c0+j*unit+dc] == 8
                 for dr in range(unit) for dc in range(unit))
             for j in range(nc)] for i in range(nr)]
    key = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,8)]
    if not key:
        return [row[:] for row in grid]
    kr0, kr1 = min(r for r,c,v in key), max(r for r,c,v in key)
    kc0, kc1 = min(c for r,c,v in key), max(c for r,c,v in key)
    kh, kw = kr1-kr0+1, kc1-kc0+1
    source = [[0]*kw for _ in range(kh)]
    for r,c,v in key:
        source[r-kr0][c-kc0] = v
    # Rotate the color key clockwise to match the silhouette's macro-cell layout.
    rotated = [[0 for _ in range(kh)] for _ in range(kw)]
    for r in range(kh):
        for c in range(kw):
            rotated[c][kh-1-r] = source[r][c]
    out = [row[:] for row in grid]
    for i in range(min(nr, len(rotated))):
        for j in range(min(nc, len(rotated[0]))):
            if not mask[i][j]:
                continue
            color = rotated[i][j]
            if color == 0:
                # Empty key positions are gaps; fill the silhouette from the nearest key color.
                candidates = [(abs(i-a) + abs(j-b), rotated[a][b])
                              for a in range(len(rotated))
                              for b in range(len(rotated[0])) if rotated[a][b] != 0]
                if candidates:
                    best = min(d for d, _ in candidates)
                    color = next(v for d, v in candidates if d == best)
            for dr in range(unit):
                for dc in range(unit):
                    out[r0+i*unit+dr][c0+j*unit+dc] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
